package ec.dmt.admin.school;
import jakarta.persistence.*;
@Entity @Table(name="enrollment",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","academic_year_id"})) public class Enrollment { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="student_id",nullable=false) private Student student; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="academic_year_id",nullable=false) private AcademicYear academicYear; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="parallel_id",nullable=false) private SchoolParallel parallel; @Column(nullable=false) private String status="ENROLLED"; protected Enrollment(){} public Enrollment(Student s,AcademicYear y,SchoolParallel p,String status){student=s;academicYear=y;parallel=p;this.status=status;} }
